def poly(xs,deg):
    cols=[np.ones_like(e)]
    for d in range(1,deg+1):
        for comb in itertools.combinations_with_replacement(range(len(xs)),d):
            c=np.ones_like(e)
            for i in comb: c=c*xs[i]
            cols.append(c)
    return np.column_stack(cols)
